#include "apex/enemy.hpp"
#include <iostream>
#include <stdexcept>
#include <limits>
using namespace apex;
void require(bool value,const char* text){if(!value)throw std::runtime_error(text);}
int main(){try{using Clock=std::chrono::steady_clock;auto start=Clock::time_point(std::chrono::seconds(100));CapturedFrame frame;frame.width=1000;frame.height=1000;frame.capturedAt=start;EnemyOptions options;EnemyContinuity filter;EnemyBox strong{.4f,.4f,.6f,.6f,.8f},weak=strong;weak.score=.4f;require(filter.update({weak},options,frame).empty(),"Unconfirmed weak candidate acquired");require(filter.update({strong},options,frame).size()==1,"Strong detection not acquired");frame.capturedAt+=std::chrono::milliseconds(16);auto other=weak;other.x1=.7f;other.x2=.9f;auto retained=filter.update({weak,other},options,frame);require(retained.size()==1&&retained[0].score==.4f&&retained[0].x1==.4f,"Weak hysteresis promoted unrelated box / changed actual score");frame.capturedAt+=std::chrono::milliseconds(16);require(filter.update({},options,frame).empty(),"Empty detection fabricated boxes");frame.capturedAt+=std::chrono::milliseconds(16);require(filter.update({weak},options,frame).size()==1,"Brief gap lost confirmed weak detection");frame.capturedAt+=std::chrono::milliseconds(300);require(filter.update({weak},options,frame).empty(),"Weak confirmation survived long gap");filter.update({strong},options,frame);options.stabilize=false;require(filter.update({weak},options,frame).empty(),"Disabled stabilization retained weak box");options.stabilize=true;filter.update({strong},options,frame);frame.width=2000;require(filter.update({weak},options,frame).empty(),"Geometry change reused confidence history");bool rejected=false;weak.score=std::numeric_limits<float>::quiet_NaN();try{filter.update({weak},options,frame);}catch(...){rejected=true;}require(rejected,"Invalid weak candidate accepted");
 EnemyDisplayCache display;EnemySnapshot snapshot;snapshot.completed=1;snapshot.status="ready";snapshot.latest.source="fixture";snapshot.latest.boxes={strong};auto source=std::make_shared<CapturedFrame>();source->width=source->height=1000;source->capturedAt=start;snapshot.analyzedFrame=source;auto shown=display.update(snapshot,200,120,true,start);require(shown.boxes.size()==1&&!shown.held,"Fresh box display failed");snapshot.completed++;snapshot.latest.boxes.clear();auto empty=std::make_shared<CapturedFrame>(*source);empty->capturedAt=start+std::chrono::milliseconds(16);snapshot.analyzedFrame=empty;shown=display.update(snapshot,200,120,true,empty->capturedAt);require(shown.boxes.size()==1&&shown.held&&snapshot.latest.boxes.empty(),"Gap display did not remain isolated from actual detection data");require(display.update(snapshot,200,120,true,start+std::chrono::milliseconds(137)).boxes.empty(),"Visual gap exceeded 120 ms");snapshot.completed++;source=std::make_shared<CapturedFrame>(*source);source->capturedAt=start+std::chrono::milliseconds(250);snapshot.analyzedFrame=source;snapshot.latest.boxes={strong};require(!display.update(snapshot,200,120,true,source->capturedAt).held,"Fresh return stayed dim");auto late=start+std::chrono::milliseconds(451);shown=display.update(snapshot,200,120,true,late);require(shown.held&&!enemyResultFresh(snapshot,200,late),"Display grace refreshed source timestamp / tracking freshness");require(display.update(snapshot,200,120,true,start+std::chrono::milliseconds(571)).boxes.empty(),"Old held box survived maximum display age");source->capturedAt=start+std::chrono::milliseconds(600);display.update(snapshot,200,120,true,source->capturedAt);snapshot.latest.source="new-source";snapshot.latest.boxes.clear();require(display.update(snapshot,200,120,true,source->capturedAt).boxes.empty(),"Display history leaked across source");snapshot.latest.boxes={strong};display.update(snapshot,200,120,true,source->capturedAt);require(display.update(snapshot,200,120,false,source->capturedAt).boxes.empty(),"Off switch retained visual box");std::cout<<"PASS confirmed-only confidence hysteresis, weak new-target rejection, gap/geometry reset, finite outputs, deterministic display-only grace/expiry/source/off behavior; no GPU/accuracy benchmark\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
